INSERT INTO `form_features` VALUES (1,'Add Product','<p data-start=\"208\" data-end=\"307\">Use this form to add a new product to the system.</p><p>\r\n</p><ul data-start=\"309\" data-end=\"1319\">\r\n<li data-start=\"309\" data-end=\"432\">\r\n<p data-start=\"311\" data-end=\"432\"><strong data-start=\"311\" data-end=\"319\">Name</strong>:<br data-start=\"320\" data-end=\"323\">\r\nEnter the product\'s name as it should appear in listings and search results.</p>\r\n</li>\r\n<li data-start=\"434\" data-end=\"562\">\r\n<p data-start=\"436\" data-end=\"562\"><strong data-start=\"436\" data-end=\"444\">Code</strong>:<br data-start=\"445\" data-end=\"448\">\r\nA unique identifier for the product</p>\r\n</li>\r\n<li data-start=\"564\" data-end=\"705\">\r\n<p data-start=\"566\" data-end=\"705\"><strong data-start=\"566\" data-end=\"574\">Type</strong>:<br data-start=\"575\" data-end=\"578\">\r\nSelect the category or type the product belongs to.</p></li></ul>','add-product',1,1,'2025-08-04 03:48:20',NULL,'2025-08-04 03:48:20'),(2,'create_user','<h2 dir=\"ltr\" style=\"line-height:1.295;text-align: justify;margin-top:10pt;margin-bottom:0pt;\" id=\"docs-internal-guid-3d09fb88-7fff-4a49-0db2-0c5b9d0dac5d\"><span style=\"font-size:12pt;font-family:Cambria,serif;color:#000000;background-color:transparent;font-weight:700;font-style:normal;font-variant:small-caps;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\"> Application Configuration</span></h2><p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:0pt;\"><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">This system enables platform administrators to configure chat handling rules, agent availability modes, and chatbot/comment bot functionality. These configurations influence how agents interact with customers and how the system handles unserved queries. The following are the key runtime settings:</span></p><h2 dir=\"ltr\" style=\"line-height:1.295;text-align: justify;margin-top:10pt;margin-bottom:0pt;\"><span style=\"font-size:12pt;font-family:Cambria,serif;color:#000000;background-color:transparent;font-weight:700;font-style:normal;font-variant:small-caps;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Chat Configuration</span></h2><br><ul style=\"margin-top:0;margin-bottom:0;padding-inline-start:48px;\"><li dir=\"ltr\" style=\"list-style-type:disc;font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.2;text-align: justify;background-color:#ffffff;margin-top:0pt;margin-bottom:0pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Add concurrent chat numbers in integer format.</span></p></li><li dir=\"ltr\" style=\"list-style-type:disc;font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.2;text-align: justify;background-color:#ffffff;margin-top:0pt;margin-bottom:0pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Add auto transfer time which an unattended chat is auto-assigned to another agent.</span></p></li><li dir=\"ltr\" style=\"list-style-type:disc;font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.2;text-align: justify;background-color:#ffffff;margin-top:0pt;margin-bottom:0pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Set message history duration for how long to retain chat messages in memory/cache.</span></p></li><li dir=\"ltr\" style=\"list-style-type:disc;font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.2;text-align: justify;background-color:#ffffff;margin-top:0pt;margin-bottom:0pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Set a time window to prioritize the last served agent for incoming chats.</span></p></li></ul><p dir=\"ltr\" style=\"line-height:1.2;text-align: justify;background-color:#ffffff;margin-top:0pt;margin-bottom:0pt;padding:0pt 0pt 11pt 0pt;\"><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;➔</span><span style=\"font-size:6.999999999999999pt;font-family:\'Times New Roman\',serif;color:#1a1a1b;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\"> &nbsp; &nbsp; </span><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Enable/Disable priority toggling.</span></p><h2 dir=\"ltr\" style=\"line-height:1.295;text-align: justify;margin-top:10pt;margin-bottom:0pt;\"><span style=\"font-size:12pt;font-family:Cambria,serif;color:#000000;background-color:transparent;font-weight:700;font-style:normal;font-variant:small-caps;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Connecting Agent Mode&nbsp;</span></h2><ul style=\"margin-top:0;margin-bottom:0;padding-inline-start:48px;\"><li dir=\"ltr\" style=\"list-style-type:disc;font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.2;text-align: justify;background-color:#ffffff;margin-top:0pt;margin-bottom:0pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Click on enable or disable supported agent status.</span></p></li><li dir=\"ltr\" style=\"list-style-type:disc;font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.2;text-align: justify;background-color:#ffffff;margin-top:0pt;margin-bottom:11pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">After select agent status then click “update button”</span></p></li></ul><p dir=\"ltr\" style=\"line-height:1.2;text-align: justify;background-color:#ffffff;margin-top:0pt;margin-bottom:11pt;\"><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Agent available mode is:</span></p><ul style=\"margin-top:0;margin-bottom:0;padding-inline-start:48px;\"><li dir=\"ltr\" style=\"list-style-type:disc;font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.2;text-align: justify;background-color:#ffffff;margin-top:0pt;margin-bottom:0pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Lunch Break: </span><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Marks the agent as unavailable during lunch.</span></p></li><li dir=\"ltr\" style=\"list-style-type:disc;font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"line-height:1.2;text-align: justify;background-color:#ffffff;margin-top:0pt;margin-bottom:0pt;\" role=\"presentation\"><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Short Break: </span><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Marks the agent as temporarily unavailable.</span></p></li></ul><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Prayer Break: </span><span style=\"font-size:11pt;font-family:Cambria,serif;color:#1a1a1b;background-color:#ffffff;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Special unavailability status.</span><p><br></p>','create-user',1,110,'2025-08-04 05:52:32',111,'2025-08-04 05:53:08');
